import { test } from 'node:test';
import { strict as assert } from 'node:assert';
import { readFileSync, mkdtempSync, writeFileSync, copyFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseYarnV1Integrity, parsePnpmIntegrity, parseBunIntegrity, readLockfileIntegrity } from '../src/detectors/lockfileIntegrity.js';

// Lockfiles generated by real `yarn install`, `pnpm install` and `bun install` (semver 7.7.2 and
// @babel/code-frame 7.27.1), so the parsers are checked against what the tools actually write.
const dir = join(dirname(fileURLToPath(import.meta.url)), 'fixtures', 'lockfile-integrity');
const read = (f: string): string => readFileSync(join(dir, f), 'utf-8');
const SEMVER_SHA512 = Buffer.from(
  'RF0Fw+rO5AMf9MAyaRXI4AV0Ulj5lMHqVxxdSgiVbixSCXoEmmX/jk0CuJw4+3SqroYO9VoUh+HcuJivvtJemA==',
  'base64'
).toString('hex');

for (const [name, parse, file] of [
  ['yarn classic', parseYarnV1Integrity, 'yarn-v1.lock'],
  ['pnpm', parsePnpmIntegrity, 'pnpm-lock.yaml'],
  ['bun', parseBunIntegrity, 'bun.lock'],
] as const) {
  test(`${name} - reads the registry hash of every package, including scoped ones`, () => {
    const hashes = parse(read(file));
    assert.deepEqual(hashes.get('semver@7.7.2'), { alg: 'SHA-512', content: SEMVER_SHA512 });
    assert.ok(hashes.has('@babel/code-frame@7.27.1'));
    assert.equal(hashes.size, 5);
  });
}

test('yarn berry and unrelated text yield no hashes rather than made-up ones', () => {
  assert.equal(parseYarnV1Integrity('__metadata:\n  version: 8\n\n"a@npm:1.0.0":\n  version: 1.0.0\n  checksum: abc\n').size, 0);
  assert.equal(parsePnpmIntegrity('lockfileVersion: 9\n').size, 0);
});

test('pnpm - git/tarball resolutions without an integrity are skipped', () => {
  const text = "packages:\n\n  foo@1.0.0:\n    resolution: {tarball: https://x.test/foo.tgz}\n\n  bar@2.0.0:\n    resolution: {integrity: sha512-AAAA}\n";
  const hashes = parsePnpmIntegrity(text);
  assert.equal(hashes.has('foo@1.0.0'), false);
  assert.equal(hashes.has('bar@2.0.0'), true);
});

test('readLockfileIntegrity - picks the parser from the project\'s lockfile', () => {
  const project = mkdtempSync(join(tmpdir(), 'integrity-'));
  try {
    writeFileSync(join(project, 'package.json'), JSON.stringify({ name: 'app', dependencies: { semver: '7.7.2' } }));
    copyFileSync(join(dir, 'pnpm-lock.yaml'), join(project, 'pnpm-lock.yaml'));
    assert.equal(readLockfileIntegrity(project).get('semver@7.7.2')?.content, SEMVER_SHA512);
  } finally {
    rmSync(project, { recursive: true, force: true });
  }
});

test('readLockfileIntegrity - a corrupt lockfile degrades to no hashes, never throws', () => {
  const project = mkdtempSync(join(tmpdir(), 'integrity-'));
  try {
    writeFileSync(join(project, 'package.json'), JSON.stringify({ name: 'app' }));
    writeFileSync(join(project, 'bun.lock'), '{ not json');
    assert.equal(readLockfileIntegrity(project).size, 0);
  } finally {
    rmSync(project, { recursive: true, force: true });
  }
});
